package org.slavicmyths.perf2;
import java.io.*;import java.nio.file.*;import java.lang.management.*;import java.util.*;import jdk.jfr.*;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.presets.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.*;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.item.*;import net.minecraft.world.effect.*;import net.minecraft.world.phys.*;
import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.event.tick.ServerTickEvent;import net.neoforged.neoforge.event.level.ChunkEvent;
/** Opt-in native input traversal, real terrain and bounded encounter/lifecycle observation. */
@EventBusSubscriber(modid="perf2audit",value=Dist.CLIENT)
public final class WorldProbe {
 static final boolean CONTROL=Boolean.getBoolean("perf.control");static final Path OUT=Path.of(System.getProperty("perf.output"));
 static final String[] NAMES=CONTROL?new String[]{"startup_warmup","idle","travel_new","travel_return","travel_settle","vanilla_village","combat_6","combat_16","cleanup"}:new String[]{"startup_warmup","idle","travel_new","travel_return","travel_settle","vanilla_village","combat_6","combat_16","mythic_combat","village","poloz","gorynych","karachun","morozko","lifecycle_1","lifecycle_2","lifecycle_3","lifecycle_4","lifecycle_5","long_idle","reload_idle"};
 static int duration(String s){return switch(s){case "startup_warmup","idle","combat_6","combat_16","mythic_combat","reload_idle"->2400;case "travel_new","travel_return","vanilla_village","village","poloz","gorynych","karachun","morozko"->3600;case "long_idle"->12000;default->1200;};}
 static PrintWriter events,ticks,frames,obs,chunks,types;static Recording rec;static ScenarioBridge bridge;static boolean opened,recording,finished,reloadRequested,reloadOpening;static volatile boolean done,setupPending;static volatile int scene,age,bootstrap;static int seenScene=-1,obsAge=-1;static long pre,lastTick,lastFrame,framePre,frameCpu,epochStart,reloadAt;static final com.sun.management.ThreadMXBean CPU=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();static String worldName,lastScreen="uninitialized";static Vec3 origin,walkCheckpoint;static float walkHeading;static int walkCheckpointAge,returnIndex=-1;static final List<Vec3> route=new ArrayList<>();static final List<LivingEntity> enemies=new ArrayList<>();static int loadedNew,loadedOld,cachedEntities;static long cachedGc,cachedGcMs;static java.lang.ref.WeakReference<net.minecraft.server.MinecraftServer> initialServer;
 static String name(){return scene<NAMES.length?NAMES[scene]:"finished";}
 static void init()throws Exception{Files.createDirectories(OUT);events=new PrintWriter(Files.newBufferedWriter(OUT.resolve("events.txt")));ticks=new PrintWriter(Files.newBufferedWriter(OUT.resolve("ticks.csv")));frames=new PrintWriter(Files.newBufferedWriter(OUT.resolve("frames.csv")));obs=new PrintWriter(Files.newBufferedWriter(OUT.resolve("observations.csv")));chunks=new PrintWriter(Files.newBufferedWriter(OUT.resolve("chunks.csv")));types=new PrintWriter(Files.newBufferedWriter(OUT.resolve("entities.csv")));types.println("scene,age,epoch_ms,type,count,with_target,no_ai");ticks.println("scene,age,epoch_ms,ms,interval_ns,heap,entities,loaded_chunks,new_chunk_events,old_chunk_events,gc_count,gc_ms,player_x,player_y,player_z,dimension,server_cpu_ns,native_mspt");frames.println("scene,age,epoch_ms,ms,render_ms,render_cpu_ms,focused,visible,iconified,paused,screen,width,height,camera_x,camera_y,camera_z,yaw,pitch,cap");obs.println("scene,age,epoch_ms,particles,sound_debug,client_entities,player_x,player_y,player_z");chunks.println("scene,age,epoch_ms,dimension,x,z,new_chunk");epochStart=System.currentTimeMillis();if(CONTROL==net.neoforged.fml.ModList.get().isLoaded("slavicmyths"))throw new IllegalStateException("Unexpected SlavicMyths presence in control/mod run");if(!CONTROL)bridge=(ScenarioBridge)Class.forName("org.slavicmyths.perf2.ModScenes").getConstructor().newInstance();events.println("PROCESS_ID="+ProcessHandle.current().pid());events.println("CONTROL="+CONTROL+" mods="+net.neoforged.fml.ModList.get().getMods().stream().map(m->m.getModId()+":"+m.getVersion()).toList());events.flush();}
 static void profile(String label){try{if(rec!=null){rec.stop();rec.dump(OUT.resolve((seenScene<0?"bootstrap":NAMES[seenScene])+".jfr"));rec.close();}rec=new Recording(Configuration.getConfiguration("profile"));rec.setMaxSize(256L*1024*1024);rec.enable("minecraft.ChunkGeneration").withThreshold(java.time.Duration.ZERO);rec.enable("minecraft.PacketSent");rec.enable("minecraft.PacketReceived");rec.start();}catch(Exception e){throw new RuntimeException(e);}}
 @SubscribeEvent public static void client(ClientTickEvent.Post event){var m=Minecraft.getInstance();if(!opened&&m.screen instanceof TitleScreen){opened=true;try{init();}catch(Exception e){throw new RuntimeException(e);}m.options.pauseOnLostFocus=false;m.options.renderDistance().set(12);m.options.simulationDistance().set(8);m.options.framerateLimit().set(140);m.options.enableVsync().set(false);m.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;m.options.save();events.println("GPU="+com.mojang.blaze3d.platform.GlUtil.getRenderer()+" window="+m.getWindow().getWidth()+"x"+m.getWindow().getHeight()+" rd12 sim8 cap="+m.options.framerateLimit().get()+" vsyncfalse");events.flush();worldName="Perf2-"+System.currentTimeMillis();m.createWorldOpenFlows().createFreshLevel(worldName,new LevelSettings(worldName,GameType.SURVIVAL,false,net.minecraft.world.Difficulty.NORMAL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(200015,true,false),r->r.registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.NORMAL).value().createWorldDimensions(),m.screen);return;}
  if(events!=null){String screen=m.screen==null?"none":m.screen.getClass().getSimpleName();if(!screen.equals(lastScreen)){lastScreen=screen;events.println("SCREEN "+screen+" epoch="+System.currentTimeMillis());events.flush();}}
  if(done&&!finished){finished=true;release(m);try{if(rec!=null){rec.stop();rec.dump(OUT.resolve("final.jfr"));rec.close();}}catch(Exception e){throw new RuntimeException(e);}events.println("COMPLETE elapsed_ms="+(System.currentTimeMillis()-epochStart));events.flush();ticks.flush();frames.flush();obs.flush();chunks.flush();types.flush();m.stop();return;}
  if(reloadRequested&&!reloadOpening){reloadOpening=true;release(m);events.println("RELOAD_REQUEST epoch="+System.currentTimeMillis()+" world="+worldName);events.flush();if(m.level!=null)m.level.disconnect();m.disconnect(new TitleScreen());reloadAt=System.currentTimeMillis();return;}
  if(reloadOpening&&m.level==null&&System.currentTimeMillis()-reloadAt>3000){reloadOpening=false;reloadRequested=false;m.createWorldOpenFlows().openWorld(worldName,()->{throw new IllegalStateException("World reopen returned to menu");});return;}
  if(m.level==null||m.player==null)return;
  if(seenScene!=scene&&scene<NAMES.length){profile(name());seenScene=scene;events.println("CLIENT_SCENE "+name()+" epoch="+System.currentTimeMillis()+" cap="+m.options.framerateLimit().get());events.flush();try(var im=Screenshot.takeScreenshot(m.getMainRenderTarget())){im.writeToFile(OUT.resolve(name()+".png"));}catch(Exception e){throw new RuntimeException(e);}}
  String n=name();boolean walking=n.equals("travel_new")||n.equals("travel_return");boolean fighting=n.startsWith("combat_")||n.equals("mythic_combat")||Set.of("poloz","gorynych","karachun","morozko").contains(n)||n.startsWith("lifecycle_");
  if(walking){if(n.equals("travel_new")){if(route.isEmpty()||age%40==0&&route.getLast().distanceToSqr(m.player.position())>.25)route.add(m.player.position());if(walkCheckpoint==null){walkCheckpoint=m.player.position();walkCheckpointAge=age;}if(age-walkCheckpointAge>=80){if(walkCheckpoint.distanceToSqr(m.player.position())<4)walkHeading+=90;walkCheckpoint=m.player.position();walkCheckpointAge=age;}m.player.setYRot(walkHeading);}else{if(returnIndex<0)returnIndex=route.size()-1;if(returnIndex>=0){var target=route.get(returnIndex);while(returnIndex>0&&target.distanceToSqr(m.player.position())<4)target=route.get(--returnIndex);var delta=target.subtract(m.player.position());m.player.setYRot((float)(Math.toDegrees(Math.atan2(delta.z,delta.x))-90));}}m.player.setXRot(8);m.options.keyUp.setDown(true);m.options.keySprint.setDown(false);m.options.keyJump.setDown(m.player.horizontalCollision||m.player.isInWater());}
  else if(fighting&&(!n.startsWith("lifecycle_")||age<=600)){LivingEntity near=null;double distance=1600;for(var a:m.level.entitiesForRendering())if((a instanceof net.minecraft.world.entity.monster.Enemy||a.getType().getCategory()==MobCategory.MONSTER)&&a instanceof LivingEntity l&&l.isAlive()){double d=m.player.distanceToSqr(a);if(d<distance){distance=d;near=l;}}if(near!=null){var delta=near.getBoundingBox().getCenter().subtract(m.player.getEyePosition());m.player.setYRot((float)(Math.toDegrees(Math.atan2(delta.z,delta.x))-90));m.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.x*delta.x+delta.z*delta.z))));m.options.keyUp.setDown(distance>5);m.options.keyJump.setDown(m.player.horizontalCollision||m.player.isInWater());if(distance<9&&m.player.tickCount%12==0&&m.gameMode!=null){m.gameMode.attack(m.player,near);m.player.swing(InteractionHand.MAIN_HAND);}}else release(m);}
  else release(m);
  if(age%20==0&&age!=obsAge){obsAge=age;obs.println(n+","+age+","+System.currentTimeMillis()+","+m.particleEngine.countParticles()+","+m.getSoundManager().getDebugString().replace(',',';')+","+java.util.stream.StreamSupport.stream(m.level.entitiesForRendering().spliterator(),false).count()+","+m.player.getX()+","+m.player.getY()+","+m.player.getZ());obs.flush();}
 }
 static void release(Minecraft m){m.options.keyUp.setDown(false);m.options.keyJump.setDown(false);m.options.keySprint.setDown(false);}
 @SubscribeEvent public static void before(ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void after(ServerTickEvent.Post event){if(events==null||done||finished)return;var s=event.getServer();if(s.getPlayerList().getPlayers().isEmpty())return;var p=s.getPlayerList().getPlayers().getFirst();var w=p.serverLevel();long now=System.nanoTime(),interval=lastTick==0?0:now-lastTick;lastTick=now;
  if(bootstrap++<100)return;
  if(origin==null){origin=p.position();initialServer=new java.lang.ref.WeakReference<>(s);w.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,s);w.setDayTime(6000);w.setWeatherParameters(0,1000000,false,false);p.getFoodData().setFoodLevel(20);for(var slot:new EquipmentSlot[]{EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET})p.setItemSlot(slot,new ItemStack(switch(slot){case HEAD->Items.DIAMOND_HELMET;case CHEST->Items.DIAMOND_CHESTPLATE;case LEGS->Items.DIAMOND_LEGGINGS;default->Items.DIAMOND_BOOTS;}));p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_SWORD));p.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,100000,4));p.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE,100000,0));events.println("ORIGIN "+origin);events.flush();}
  if(!p.isAlive()||p.getY()<w.getMinBuildHeight()){events.println("INVALID_PLAYER_DEAD_OR_VOID "+name()+" age="+age);events.flush();done=true;return;}
  age++;if(age%100==0){p.getFoodData().setFoodLevel(20);p.setHealth(p.getMaxHealth());}
  if(age==1){setup(name(),w,p);events.println("SERVER_SCENE "+name()+" epoch="+System.currentTimeMillis()+" position="+p.position());events.flush();}
  if(bridge!=null)bridge.tick(name(),age,w,p,events);
  if(age%20==0){cachedGc=0;cachedGcMs=0;for(var bean:ManagementFactory.getGarbageCollectorMXBeans()){cachedGc+=bean.getCollectionCount();cachedGcMs+=bean.getCollectionTime();}cachedEntities=0;for(var entity:w.getAllEntities())cachedEntities++;}
  var rt=Runtime.getRuntime();ticks.println(name()+","+age+","+System.currentTimeMillis()+","+(now-pre)/1e6+","+interval+","+(rt.totalMemory()-rt.freeMemory())+","+cachedEntities+","+w.getChunkSource().getLoadedChunksCount()+","+loadedNew+","+loadedOld+","+cachedGc+","+cachedGcMs+","+p.getX()+","+p.getY()+","+p.getZ()+","+w.dimension().location()+","+CPU.getCurrentThreadCpuTime()+","+s.getTickTimesNanos()[s.getTickCount()%100]/1e6);if(age%100==0){ticks.flush();Map<String,int[]> counts=new TreeMap<>();for(var entity:w.getAllEntities()){var row=counts.computeIfAbsent(BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString(),k->new int[3]);row[0]++;if(entity instanceof Mob mob){if(mob.getTarget()!=null)row[1]++;if(mob.isNoAi())row[2]++;}}for(var entry:counts.entrySet()){var row=entry.getValue();types.println(name()+","+age+","+System.currentTimeMillis()+","+entry.getKey()+","+row[0]+","+row[1]+","+row[2]);}types.flush();}

  if(age>=duration(name())){events.println("END "+name()+" epoch="+System.currentTimeMillis()+" position="+p.position()+" status="+(bridge==null?"control":bridge.status()));events.flush();if(bridge!=null)bridge.finish(name(),w,p,events);if(name().startsWith("combat_")){events.println("BEFORE_COMMON_CLEANUP "+name()+" alive="+enemies.stream().filter(a->a.isAlive()&&!a.isRemoved()).count());for(var a:enemies)if(!a.isRemoved())a.discard();enemies.clear();events.flush();}age=0;scene++;if(scene>=NAMES.length){done=true;return;}if(name().equals("reload_idle")){p.getPersistentData().putString("Perf2Checkpoint","saved-native-world");s.saveEverything(false,true,true);reloadRequested=true;bootstrap=0;events.println("SAVED_BEFORE_RELOAD");events.flush();}}
  if(name().equals("reload_idle")&&age==120){events.println("RELOAD_VERIFY new_server="+(s!=initialServer.get())+" old_server_collected="+(initialServer.get()==null)+" marker="+p.getPersistentData().getString("Perf2Checkpoint"));events.flush();}
 }
 static void setup(String n,ServerLevel w,ServerPlayer p){if(n.equals("vanilla_village")){long before=System.nanoTime();var q=w.findNearestMapStructure(net.minecraft.tags.StructureTags.VILLAGE,p.blockPosition(),1,false);if(q!=null){w.getChunk(q.getX()>>4,q.getZ()>>4);var floor=w.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,q);p.teleportTo(w,floor.getX()+.5,floor.getY(),floor.getZ()+.5,0,12);events.println("NATIVE_VILLAGE_FOUND "+q+" setup_ms="+(System.nanoTime()-before)/1e6);}else events.println("NATIVE_VILLAGE_NOT_FOUND bounded_radius1");events.flush();}if(n.startsWith("combat_")){int count=n.equals("combat_6")?6:16;for(int i=0;i<count;i++){var type=count==16&&i%4==0?EntityType.PILLAGER:i%3==0?EntityType.SKELETON:EntityType.ZOMBIE;var mob=type.create(w);var q=p.blockPosition().offset(i%5*2-4,0,8+i/5*2);var floor=w.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,q);mob.moveTo(floor.getX()+.5,floor.getY(),floor.getZ()+.5,180,0);mob.finalizeSpawn(w,w.getCurrentDifficultyAt(floor),MobSpawnType.COMMAND,null);mob.setTarget(p);if(mob instanceof Zombie)mob.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));w.addFreshEntity(mob);enemies.add(mob);}}if(bridge!=null)bridge.setup(n,w,p,events);}
 @SubscribeEvent public static void chunk(ChunkEvent.Load e){if(events==null||!(e.getLevel() instanceof ServerLevel level))return;if(e.isNewChunk())loadedNew++;else loadedOld++;var c=e.getChunk().getPos();chunks.println(name()+","+age+","+System.currentTimeMillis()+","+level.dimension().location()+","+c.x+","+c.z+","+e.isNewChunk());if(age%100==0)chunks.flush();}
 @SubscribeEvent public static void frameBefore(RenderFrameEvent.Pre e){framePre=System.nanoTime();frameCpu=CPU.getCurrentThreadCpuTime();}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e){long now=System.nanoTime(),cpu=CPU.getCurrentThreadCpuTime();var m=Minecraft.getInstance();if(m.level!=null&&m.player!=null&&!done&&events!=null){long win=m.getWindow().getWindow();var c=m.gameRenderer.getMainCamera();var p=c.getPosition();frames.println(name()+","+age+","+System.currentTimeMillis()+","+(lastFrame==0?0:(now-lastFrame)/1e6)+","+(now-framePre)/1e6+","+(cpu-frameCpu)/1e6+","+m.isWindowActive()+","+org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(win,org.lwjgl.glfw.GLFW.GLFW_VISIBLE)+","+org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(win,org.lwjgl.glfw.GLFW.GLFW_ICONIFIED)+","+m.isPaused()+","+(m.screen==null?"none":m.screen.getClass().getSimpleName())+","+m.getWindow().getWidth()+","+m.getWindow().getHeight()+","+p.x+","+p.y+","+p.z+","+c.getYRot()+","+c.getXRot()+","+m.options.framerateLimit().get());if(age%100==0)frames.flush();}lastFrame=now;}
}
